void ShaderTextEditor::set_edited_resource(const Ref<Resource> &res) {
	if (res.is_null() || edited_res == res) {
		return;
	}
	if (edited_res.is_valid()) {
		edited_res->disconnect_changed(callable_mp(this, &ShaderTextEditor::_shader_changed));
	}

	Ref<Shader> shader = res;
	Ref<ShaderInclude> shader_inc = res;
	if (shader.is_null() && shader_inc.is_null()) {
		return;
	}

	edited_res = res;
	_load_theme_settings();

	String code;
	if (shader.is_valid()) {
		code = shader->get_code();
	} else if (shader_inc.is_valid()) {
		code = shader_inc->get_code();
	}
	code_editor->get_text_editor()->set_text(code);
	code_editor->get_text_editor()->clear_undo_history();
	callable_mp((TextEdit *)code_editor->get_text_editor(), &TextEdit::set_h_scroll).call_deferred(0);
	callable_mp((TextEdit *)code_editor->get_text_editor(), &TextEdit::set_v_scroll).call_deferred(0);
	code_editor->get_text_editor()->tag_saved_version();

	_validate_script();
	code_editor->update_line_and_column();

	edited_res->connect_changed(callable_mp(this, &ShaderTextEditor::_shader_changed));
}
